// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"Para que serve uma reunião pedagógica","html":"<p>A reunião pedagógica é o principal momento de formação dentro da escola. Ela funciona quando termina com uma decisão sobre a prática em sala e com uma data para conferir o que mudou.</p><p>Este guia propõe um método simples, que usa os dados do reforço escolar como ponto de partida e deixa a decisão com os professores.</p><h3>Ao final, você será capaz de</h3><ul><li>Preparar uma pauta com um único foco.</li><li>Conduzir a reunião no tempo previsto, com a participação de todos.</li><li>Usar os dados da plataforma sem expor alunos nem professores.</li><li>Lidar com resistência, silêncio e conflito na equipe.</li><li>Registrar os combinados e acompanhar a execução.</li></ul><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tipo de reunião</th><th>Finalidade</th><th>Frequência sugerida</th></tr></thead><tbody><tr><td>Planejamento</td><td>Definir o que retomar com as turmas.</td><td>Quinzenal</td></tr><tr><td>Estudo</td><td>Aprofundar uma habilidade ou uma estratégia de ensino.</td><td>Mensal</td></tr><tr><td>Conselho de classe</td><td>Analisar a turma e decidir apoios para alunos.</td><td>Bimestral</td></tr><tr><td>Acompanhamento</td><td>Conferir os combinados anteriores.</td><td>Na reunião seguinte</td></tr></tbody></table></div>"},{"id":"c2","titulo":"O ciclo da reunião","html":"<figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Preparar</b><small>Escolher um foco, levantar os dados e montar a pauta.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Conduzir</b><small>Abrir, analisar, decidir e fechar no tempo.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Registrar</b><small>Anotar quem faz o quê e até quando.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Acompanhar</b><small>Apoiar a execução e conferir na reunião seguinte.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. Uma reunião só termina quando o combinado é conferido.</figcaption></figure><div class=\"nota\"><b>Um foco por reunião</b><br/>Reuniões com muitos assuntos terminam sem decisão. Avisos administrativos vão por escrito, antes ou depois.</div>"},{"id":"c3","titulo":"Como preparar","html":"<ol class=\"passos\"><li>Escolha o foco. Um bom ponto de partida é a tela <b>Habilidades prioritárias</b>: a habilidade com mais alunos em Ainda não.</li><li>Levante os dados. Em <b>Aprendizagem</b>, veja a prática e a recuperação das turmas envolvidas.</li><li>Prepare uma pergunta de trabalho. Por exemplo: o que faremos nas próximas duas semanas para a turma avançar em frações?</li><li>Monte a pauta com tempos e envie com antecedência.</li><li>Converse antes com quem será mais afetado pelo tema, para que não seja surpreendido.</li></ol><h3>Modelo de pauta</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Etapa</th><th>Quem conduz</th><th>Resultado</th></tr></thead><tbody><tr><td>5 min</td><td>Abertura e objetivo</td><td>Coordenação</td><td>Todos sabem o que será decidido.</td></tr><tr><td>10 min</td><td>Retorno dos combinados anteriores</td><td>Cada professor</td><td>O que funcionou e o que não funcionou.</td></tr><tr><td>10 min</td><td>Leitura dos dados</td><td>Coordenação</td><td>Um retrato comum da situação.</td></tr><tr><td>15 min</td><td>Análise e propostas</td><td>Professores, em duplas</td><td>Duas ou três propostas concretas.</td></tr><tr><td>10 min</td><td>Decisão e combinados</td><td>Todos</td><td>Quem faz o quê e até quando.</td></tr><tr><td>5 min</td><td>Fechamento</td><td>Coordenação</td><td>Data da conferência.</td></tr></tbody></table></div>"},{"id":"c4","titulo":"Como apresentar dados sem expor ninguém","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td>Mostrar a habilidade e o percentual de alunos em cada nível.</td><td>Projetar a tela com os nomes dos alunos.</td></tr><tr><td>Comparar a turma com ela mesma, antes e depois.</td><td>Comparar professores ou turmas entre si.</td></tr><tr><td>Perguntar o que os dados sugerem.</td><td>Anunciar a conclusão antes de ouvir a equipe.</td></tr><tr><td>Tratar casos de alunos em conversa reservada.</td><td>Discutir a situação familiar de um aluno diante de todos.</td></tr></tbody></table></div><h3>Perguntas que abrem a análise</h3><ul><li>O que mais chamou a atenção nestes dados?</li><li>O que pode explicar essa dificuldade?</li><li>O que já tentamos e qual foi o resultado?</li><li>O que está ao nosso alcance fazer nas próximas duas semanas?</li><li>Como saberemos se deu certo?</li></ul>"},{"id":"c5","titulo":"Como conduzir","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Abrir</b><small>objetivo e regras do encontro</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Ouvir</b><small>retorno dos combinados</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Analisar</b><small>dados e causas</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Decidir</b><small>uma ação por professor</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Fechar</b><small>registro e data</small></div></div><figcaption>Figura. Os cinco momentos da condução.</figcaption></figure><h3>Técnicas para a participação</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Técnica</th><th>Como fazer</th><th>Quando usar</th></tr></thead><tbody><tr><td>Pensar, conversar em dupla, compartilhar</td><td>Um minuto individual, três em dupla, depois o grupo.</td><td>Quando poucos falam.</td></tr><tr><td>Rodada</td><td>Cada pessoa fala por até um minuto, sem interrupção.</td><td>Para ouvir todos sobre um ponto.</td></tr><tr><td>Estacionamento</td><td>Assuntos fora do foco vão para uma lista e são tratados depois.</td><td>Quando a conversa se desvia.</td></tr><tr><td>Uma ação por pessoa</td><td>Cada professor escolhe uma ação pequena e possível.</td><td>Na hora de decidir.</td></tr></tbody></table></div>"},{"id":"c6","titulo":"Situações difíceis na reunião","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que costuma estar por trás</th><th>Como agir</th></tr></thead><tbody><tr><td>Silêncio geral</td><td>Medo de exposição ou pauta pouco clara.</td><td>Usar duplas antes do grupo e reformular a pergunta.</td></tr><tr><td>\"Isso não funciona com a minha turma\"</td><td>Cansaço ou experiência anterior ruim.</td><td>Perguntar o que já foi tentado e o que seria possível testar em pequena escala.</td></tr><tr><td>Um professor domina a fala</td><td>Vontade de contribuir ou ansiedade.</td><td>Usar rodada com tempo e agradecer, passando a palavra.</td></tr><tr><td>Dados contestados</td><td>Receio de ser avaliado.</td><td>Lembrar que os dados mostram o momento do aluno e não avaliam professores.</td></tr><tr><td>Conflito entre colegas</td><td>Divergência antiga ou sobrecarga.</td><td>Interromper com calma, voltar ao foco e conversar em separado depois.</td></tr><tr><td>Queixas sobre condições de trabalho</td><td>Problema real, fora do alcance da reunião.</td><td>Registrar, levar à direção e dar retorno na reunião seguinte.</td></tr></tbody></table></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a equipe que não queria olhar os dados</div><p><b>Situação.</b> Na primeira reunião com dados do reforço, parte dos professores diz que os números servem para vigiar o trabalho deles.</p><p><b>O que fazer.</b></p><ol><li>Abra dizendo para que os dados servem e para que não servem.</li><li>Mostre apenas o resultado da escola, sem turmas nem nomes.</li><li>Peça que cada dupla escolha uma habilidade para olhar com mais atenção.</li><li>Feche com uma ação escolhida pelos próprios professores.</li></ol><p><b>Resultado esperado.</b> A equipe passa a pedir os dados nas reuniões seguintes, porque eles ajudam a planejar.</p></div>"},{"id":"c7","titulo":"Registro e acompanhamento","html":"<p>O registro curto, feito na hora, vale mais do que uma ata longa enviada dias depois.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O quê</th><th>Quem</th><th>Até quando</th><th>Como saberemos</th></tr></thead><tbody><tr><td>Retomar frações com material concreto no 6º B</td><td>Professora de Matemática</td><td>Duas semanas</td><td>Menos alunos em Ainda não no mapa da turma</td></tr><tr><td>Indicar reforço aos responsáveis de oito alunos</td><td>Professora de Matemática</td><td>Esta semana</td><td>Avisos enviados e prática registrada</td></tr><tr><td>Abrir o laboratório no contraturno</td><td>Direção</td><td>Próxima segunda</td><td>Lista de alunos atendidos</td></tr></tbody></table></div><ul class=\"chk\"><li><span></span>Cada combinado tem um responsável e uma data.</li><li><span></span>O registro foi enviado a todos no mesmo dia.</li><li><span></span>A coordenação passou nas salas ou conversou com os professores no intervalo entre as reuniões.</li><li><span></span>A reunião seguinte começou pelo retorno dos combinados.</li></ul>"},{"id":"c8","titulo":"O tempo de trabalho coletivo","html":"<p>A reunião pedagógica é parte da jornada do professor, e não um favor. A Lei de Diretrizes e Bases (art. 67) inclui na carga de trabalho um período reservado a estudos, planejamento e avaliação. A Lei nº 11.738/2008 reserva no mínimo um terço da jornada para atividades sem alunos.</p><p>Esse tempo é o recurso mais valioso do coordenador. Uma hora de reunião com vinte professores custa vinte horas de trabalho da escola. Por isso cada encontro precisa ter objetivo e resultado.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tipo de encontro</th><th>Para que serve</th><th>Frequência comum</th><th>Quem participa</th></tr></thead><tbody><tr><td>Planejamento coletivo</td><td>Alinhar o que será ensinado e como.</td><td>Semanal ou quinzenal</td><td>Professores do ano ou da área</td></tr><tr><td>Formação</td><td>Estudar um tema e mudar uma prática.</td><td>Mensal</td><td>Toda a equipe docente</td></tr><tr><td>Análise de dados</td><td>Ler os resultados e decidir prioridades.</td><td>A cada bimestre</td><td>Professores e coordenação</td></tr><tr><td>Estudo de caso</td><td>Buscar estratégias para um aluno ou uma turma.</td><td>Quando necessário</td><td>Professores do aluno</td></tr><tr><td>Conselho de classe</td><td>Avaliar o percurso das turmas e decidir encaminhamentos.</td><td>A cada bimestre</td><td>Professores, coordenação e direção</td></tr><tr><td>Reunião geral</td><td>Informar e combinar a organização da escola.</td><td>No início de cada período</td><td>Toda a equipe</td></tr></tbody></table></div><div class=\"nota\"><b>Uma reunião, um tipo</b><br/>Misturar formação, avisos e conselho no mesmo encontro costuma fazer com que nenhum dos três aconteça bem. Avisos podem ir por escrito.</div><div class=\"pratica\"><div class=\"tt\">Para praticar · o tempo da sua escola</div><div class=\"q\"><b>1.</b> Quantas horas de trabalho coletivo a sua escola tem por mês?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Quanto desse tempo foi usado para avisos no último mês?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c9","titulo":"O calendário anual de reuniões","html":"<p>Um calendário definido no início do ano evita reuniões marcadas às pressas e permite que os professores se preparem.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Período</th><th>Foco das reuniões</th><th>Resultado esperado</th></tr></thead><tbody><tr><td>Semana pedagógica</td><td>Acolhida, leitura dos resultados do ano anterior, combinados e planejamento do primeiro bimestre.</td><td>Plano de ação da escola e planos de ensino.</td></tr><tr><td>Primeiro mês</td><td>Diagnóstico inicial das turmas.</td><td>Mapa do que cada turma precisa retomar.</td></tr><tr><td>Meio do 1º bimestre</td><td>Formação no tema prioritário do plano.</td><td>Uma prática combinada para testar.</td></tr><tr><td>Fim de cada bimestre</td><td>Conselho de classe e análise de dados.</td><td>Encaminhamentos por turma e por aluno.</td></tr><tr><td>Início de cada bimestre</td><td>Planejamento com base no conselho.</td><td>Ajustes nos planos de ensino.</td></tr><tr><td>Meio do ano</td><td>Balanço do plano de ação.</td><td>O que manter, o que mudar.</td></tr><tr><td>Último mês</td><td>Avaliação do ano e registro para o ano seguinte.</td><td>Relatório curto e prioridades.</td></tr></tbody></table></div><h3>A semana pedagógica em cinco blocos</h3><ol class=\"passos\"><li><b>Acolhida:</b> receber os novos, apresentar a equipe e retomar o que a escola valoriza.</li><li><b>Onde estamos:</b> ler os resultados do ano anterior, sem buscar culpados.</li><li><b>Para onde vamos:</b> escolher duas ou três prioridades.</li><li><b>Como vamos:</b> definir ações, responsáveis e datas.</li><li><b>Planejamento:</b> tempo protegido para os professores planejarem por ano e por área.</li></ol><div class=\"nota alerta\"><b>Cuidado com a semana de palestras</b><br/>Uma semana inteira de palestras cansa e muda pouco. Reserve ao menos metade do tempo para o planejamento dos professores.</div>"},{"id":"c10","titulo":"A pauta que funciona","html":"<p>A pauta é o roteiro do encontro. Uma boa pauta diz o que se quer alcançar, e não apenas os assuntos.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pauta fraca</th><th>Pauta forte</th></tr></thead><tbody><tr><td>\"Avaliação.\"</td><td>\"Decidir como vamos retomar frações no 6º ano.\"</td></tr><tr><td>\"Informes.\"</td><td>\"Informes enviados por escrito. Dúvidas em cinco minutos.\"</td></tr><tr><td>\"Indisciplina.\"</td><td>\"Combinar três regras comuns para o 8º B.\"</td></tr><tr><td>\"Projeto de leitura.\"</td><td>\"Definir datas e responsáveis do projeto de leitura.\"</td></tr></tbody></table></div><h3>Modelo de pauta</h3><div class=\"rapido\"><p><b>Reunião de:</b> ____________________ <b>Data e horário:</b> ____/____/______, das ______ às ______</p><p><b>Objetivo (o que teremos ao final):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Antes da reunião, cada um deve:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Assunto</th><th>Como</th><th>Quem conduz</th><th>Resultado</th></tr></thead><tbody><tr><td>10 min</td><td></td><td></td><td></td><td></td></tr><tr><td>30 min</td><td></td><td></td><td></td><td></td></tr><tr><td>15 min</td><td></td><td></td><td></td><td></td></tr><tr><td>5 min</td><td>Encaminhamentos</td><td>Leitura do que foi combinado</td><td>Coordenação</td><td>Quadro de ações</td></tr></tbody></table></div></div><h3>Regras de uma boa pauta</h3><ul><li>No máximo três assuntos.</li><li>Cada assunto escrito como verbo: decidir, combinar, analisar, planejar.</li><li>O assunto mais importante vem primeiro.</li><li>Tempo previsto para cada item, com alguém que controla o relógio.</li><li>Enviada com dois dias de antecedência.</li><li>Os últimos cinco minutos são sempre dos encaminhamentos.</li></ul>"},{"id":"c11","titulo":"Técnicas para todos participarem","html":"<p>Em reuniões conduzidas só por fala, três ou quatro pessoas participam e as outras ouvem. As técnicas abaixo distribuem a palavra e produzem resultado em pouco tempo.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Técnica</th><th>Como funciona</th><th>Quando usar</th><th>Tempo</th></tr></thead><tbody><tr><td>Um, dois, todos</td><td>Cada um pensa sozinho, depois conversa em dupla, depois as duplas falam ao grupo.</td><td>Para qualquer pergunta que pede reflexão.</td><td>10 min</td></tr><tr><td>Rodada</td><td>Cada pessoa fala uma frase, em ordem, sem comentário dos demais.</td><td>Na abertura e no fechamento.</td><td>5 min</td></tr><tr><td>Papéis no quadro</td><td>Cada um escreve ideias em papéis, uma por papel. O grupo agrupa as parecidas.</td><td>Para levantar causas e propostas.</td><td>15 min</td></tr><tr><td>Galeria</td><td>Grupos registram em cartazes. Todos circulam, leem e anotam comentários.</td><td>Para conhecer o trabalho de outras áreas.</td><td>20 min</td></tr><tr><td>Mesas rotativas</td><td>Cada mesa discute uma pergunta. A cada dez minutos, as pessoas trocam de mesa.</td><td>Para temas com vários aspectos.</td><td>30 min</td></tr><tr><td>Advogado da ideia</td><td>Antes de criticar uma proposta, o grupo lista o que ela tem de bom.</td><td>Quando propostas são derrubadas rápido demais.</td><td>10 min</td></tr><tr><td>Votação por pontos</td><td>Cada pessoa tem três votos para distribuir entre as opções.</td><td>Para priorizar.</td><td>5 min</td></tr></tbody></table></div><h3>Boas perguntas abrem a conversa</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Pergunte</th></tr></thead><tbody><tr><td>\"Alguma dúvida?\"</td><td>\"Que dúvida vocês acham que um professor novo teria?\"</td></tr><tr><td>\"Todos concordam?\"</td><td>\"O que precisaria mudar para esta proposta funcionar na sua turma?\"</td></tr><tr><td>\"Por que os alunos não aprendem?\"</td><td>\"O que os alunos que aprenderam fizeram de diferente?\"</td></tr><tr><td>\"Quem tem uma sugestão?\"</td><td>\"Escrevam duas ideias. Depois ouvimos uma de cada.\"</td></tr></tbody></table></div>"},{"id":"c12","titulo":"A reunião de formação","html":"<p>Formar professores na escola é ajudar adultos experientes a rever a prática. Adultos aprendem melhor quando o tema resolve um problema real, quando podem usar o que já sabem e quando experimentam antes de avaliar.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>Na prática</th></tr></thead><tbody><tr><td>Parte de um problema real</td><td>O tema vem dos dados e das dificuldades relatadas pela equipe.</td></tr><tr><td>Valoriza a experiência</td><td>Começa perguntando o que cada um já faz.</td></tr><tr><td>Mostra, não só explica</td><td>Traz um exemplo de aula, um vídeo curto ou uma atividade de aluno.</td></tr><tr><td>Põe para fazer</td><td>Os professores planejam uma aula ou uma atividade durante a reunião.</td></tr><tr><td>Combina um teste</td><td>Cada um escolhe o que vai experimentar até o próximo encontro.</td></tr><tr><td>Volta ao tema</td><td>O encontro seguinte começa com o relato do que foi testado.</td></tr></tbody></table></div><figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Estudar</b><small>Um texto curto, um exemplo ou um dado.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Planejar</b><small>Uma aula ou atividade com a ideia estudada.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Aplicar</b><small>Na própria turma, até o próximo encontro.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Relatar</b><small>O que funcionou, o que não funcionou e por quê.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo de uma formação que muda a prática.</figcaption></figure><h3>Roteiro de uma formação de 90 minutos</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Etapa</th><th>O que acontece</th></tr></thead><tbody><tr><td>10 min</td><td>Retomada</td><td>Relato do que foi testado desde o último encontro.</td></tr><tr><td>15 min</td><td>Problema</td><td>Apresentação de um dado ou de uma situação da escola.</td></tr><tr><td>20 min</td><td>Estudo</td><td>Leitura curta ou análise de um exemplo, em duplas.</td></tr><tr><td>30 min</td><td>Planejamento</td><td>Cada dupla prepara uma atividade para aplicar.</td></tr><tr><td>10 min</td><td>Partilha</td><td>Três duplas apresentam.</td></tr><tr><td>5 min</td><td>Combinado</td><td>O que cada um vai testar e quando.</td></tr></tbody></table></div><div class=\"nota\"><b>Um tema por semestre</b><br/>Trocar de tema a cada reunião não muda a prática. Escolha um tema e fique nele por vários encontros.</div>"},{"id":"c13","titulo":"Estudo de caso de um aluno","html":"<p>Quando um aluno preocupa vários professores, o estudo de caso reúne o que cada um sabe e termina com um plano. Ele dura de vinte a trinta minutos por aluno.</p><ol class=\"passos\"><li><b>Apresentação (3 min):</b> quem trouxe o caso descreve o aluno em fatos: frequência, o que faz, o que não faz.</li><li><b>O que funciona (5 min):</b> cada professor diz em que momento o aluno participa ou aprende melhor.</li><li><b>O que dificulta (5 min):</b> o que cada um observa, sem rótulos.</li><li><b>Hipóteses (5 min):</b> o grupo levanta possíveis causas.</li><li><b>Estratégias (7 min):</b> o grupo escolhe duas ou três ações comuns a todos.</li><li><b>Plano (5 min):</b> quem faz o quê, quem fala com a família e quando o caso volta à pauta.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Evite</th><th>Prefira</th></tr></thead><tbody><tr><td>\"Ele não quer nada.\"</td><td>\"Ele entrega a atividade quando trabalha em dupla.\"</td></tr><tr><td>\"A família não ajuda.\"</td><td>\"A mãe trabalha à noite. Vamos combinar outro horário de contato.\"</td></tr><tr><td>\"Já tentei de tudo.\"</td><td>\"Tentei mudar de lugar por uma semana. O que mais podemos testar?\"</td></tr><tr><td>\"Isso é caso para especialista.\"</td><td>\"O que podemos fazer em sala enquanto a família busca avaliação?\"</td></tr></tbody></table></div><h3>Ficha do estudo de caso</h3><div class=\"rapido\"><p><b>Aluno (iniciais), ano e turma:</b> ____________________ <b>Data:</b> ____/____/______</p><p><b>O que já funciona:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que preocupa (fatos):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Estratégias combinadas por todos:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Contato com os responsáveis (quem e quando):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Data de retorno do caso:</b> ____/____/______</p></div><div class=\"nota alerta\"><b>Sigilo</b><br/>O estudo de caso trata de informações pessoais. A ficha fica com a coordenação, e o que se discute não sai da sala.</div>"},{"id":"c14","titulo":"Conselho de classe com foco na aprendizagem","html":"<p>O conselho de classe avalia o percurso da turma e de cada aluno e decide o que a escola fará. Ele perde o sentido quando vira uma leitura de notas ou um julgamento do comportamento.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento</th><th>O que fazer</th></tr></thead><tbody><tr><td>Antes</td><td>A coordenação reúne os dados: frequência, resultados, habilidades prioritárias da turma no reforço. Cada professor indica os alunos que preocupam e os que avançaram.</td></tr><tr><td>Abertura</td><td>Retomar os encaminhamentos do conselho anterior: o que foi feito e o que mudou.</td></tr><tr><td>A turma</td><td>Olhar a turma inteira: o que aprendeu, o que falta, como está a convivência.</td></tr><tr><td>Os alunos</td><td>Discutir os alunos indicados, com o roteiro do estudo de caso resumido.</td></tr><tr><td>A escola</td><td>Perguntar o que o ensino precisa mudar, e não apenas o que o aluno precisa mudar.</td></tr><tr><td>Fechamento</td><td>Registrar os encaminhamentos, com responsável e data.</td></tr><tr><td>Depois</td><td>Dar retorno aos alunos e aos responsáveis. Acompanhar os encaminhamentos.</td></tr></tbody></table></div><h3>Perguntas que orientam o conselho</h3><ul><li>O que esta turma aprendeu neste bimestre?</li><li>Que habilidades a maioria ainda não domina?</li><li>Quem avançou e o que explica esse avanço?</li><li>Quem precisa de apoio e de que tipo?</li><li>O que nós, professores, vamos fazer diferente?</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Fala a evitar</th><th>Como reformular</th></tr></thead><tbody><tr><td>\"Esse aluno é fraco.\"</td><td>\"Ele ainda não domina a leitura de textos longos.\"</td></tr><tr><td>\"Essa turma é a pior da escola.\"</td><td>\"Nesta turma, a maioria não fez as atividades de casa. O que explica?\"</td></tr><tr><td>\"Não tem jeito.\"</td><td>\"O que ainda não tentamos?\"</td></tr></tbody></table></div><div class=\"nota\"><b>A participação dos alunos</b><br/>Muitas escolas ouvem representantes de turma antes do conselho. A escuta traz informações que os adultos não têm e fortalece o compromisso dos alunos com os combinados.</div>"},{"id":"c15","titulo":"Analisar trabalhos dos alunos em grupo","html":"<p>Olhar juntos para o que os alunos produziram é uma das formações mais eficazes. Mostra o que a turma realmente sabe e alinha o que cada professor entende por um bom trabalho.</p><ol class=\"passos\"><li>Um professor traz três produções da mesma atividade: uma que atingiu o esperado, uma mediana e uma que ficou distante. Os nomes são ocultados.</li><li>Ele explica a atividade e o que esperava, em dois minutos.</li><li>O grupo observa em silêncio por cinco minutos.</li><li>O grupo descreve o que vê, sem julgar: \"ele organizou em parágrafos\", \"ela não usou a fórmula\".</li><li>O grupo interpreta: o que cada aluno parece saber e o que ainda não sabe.</li><li>O grupo sugere o próximo passo de ensino para cada um.</li><li>O professor que trouxe diz o que leva da conversa.</li></ol><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Descrever</th><th>Interpretar</th><th>Decidir</th></tr></thead><tbody><tr><td>\"Há três erros de regra de sinal.\"</td><td>\"Ela sabe montar a equação, mas não domina os sinais.\"</td><td>\"Retomar operações com negativos antes de seguir.\"</td></tr><tr><td>\"O texto tem um só parágrafo.\"</td><td>\"Ele tem ideias, mas não as organiza.\"</td><td>\"Ensinar a planejar o texto antes de escrever.\"</td></tr></tbody></table></div><div class=\"nota\"><b>Regra de ouro</b><br/>O grupo analisa o trabalho do aluno, e não o trabalho do professor. Quem traz as produções está fazendo um favor ao grupo.</div>"},{"id":"c16","titulo":"Observação de aula e devolutiva","html":"<p>A observação de aula é uma forma de apoio, e não de fiscalização. Ela só funciona quando há confiança, combinado prévio e devolutiva rápida.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Combinar</b><small>data e foco, com o professor</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Observar</b><small>registrar fatos, sem interferir</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Conversar</b><small>em até dois dias</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Acompanhar</b><small>voltar ao combinado</small></div></div><figcaption>Figura. O ciclo da observação de aula.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>Faça</th><th>Evite</th></tr></thead><tbody><tr><td>Antes</td><td>Perguntar ao professor o que ele quer que você observe.</td><td>Entrar sem avisar.</td></tr><tr><td>Durante</td><td>Anotar o que o professor e os alunos fazem e dizem, com horário.</td><td>Interromper ou corrigir diante da turma.</td></tr><tr><td>Depois</td><td>Conversar em particular, começando pelo que o professor percebeu.</td><td>Entregar uma lista de defeitos.</td></tr></tbody></table></div><h3>O que anotar</h3><ul><li>Quanto tempo a turma passou ouvindo e quanto tempo passou fazendo.</li><li>Quantos alunos participaram e quais.</li><li>As perguntas que o professor fez.</li><li>O momento em que a atenção caiu.</li><li>Um trecho que funcionou bem.</li></ul><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · a devolutiva</div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Obrigada por me receber. Como você sentiu a aula?</div></div><div class=\"f o\"><div class=\"q\">Professor</div><div class=\"b\">Achei que a turma dispersou no final.</div></div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Anotei que até 9h20 quase todos faziam a atividade. Depois da correção no quadro, oito alunos pararam. O que você acha que aconteceu?</div></div><div class=\"f o\"><div class=\"q\">Professor</div><div class=\"b\">A correção ficou longa. Só quem errou precisava dela.</div></div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">O que você poderia testar na próxima aula?</div></div><div class=\"f o\"><div class=\"q\">Professor</div><div class=\"b\">Corrigir em duplas e passar nas mesas.</div></div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Combinado. Posso voltar em duas semanas para ver como ficou?</div></div></div><div class=\"nota\"><b>Uma coisa por vez</b><br/>Uma boa devolutiva termina com um único ponto de melhoria, escolhido pelo professor. Quem recebe cinco orientações não muda nenhuma.</div>"},{"id":"c17","titulo":"Como lidar com cada perfil na reunião","html":"<p>Todo grupo tem pessoas que participam de formas diferentes. O coordenador não muda as pessoas, mas pode organizar a reunião para que todas contribuam.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Perfil</th><th>Como aparece</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Quem fala muito</td><td>Ocupa o tempo e responde a todas as perguntas.</td><td>Usar rodadas e duplas. Agradecer e passar a palavra: \"Vamos ouvir quem ainda não falou.\"</td></tr><tr><td>Quem não fala</td><td>Fica em silêncio, mesmo tendo boas ideias.</td><td>Dar tempo para escrever antes de falar. Conversar em duplas.</td></tr><tr><td>Quem resiste</td><td>Diz que nada funciona ou que já viu isso antes.</td><td>Ouvir a objeção, pedir que diga o que funcionaria e propor um teste curto.</td></tr><tr><td>Quem está chegando</td><td>Tem receio de se expor diante dos mais antigos.</td><td>Formar duplas com um colega acolhedor. Perguntar em particular do que precisa.</td></tr><tr><td>Quem tem muita experiência</td><td>Sente que não tem o que aprender.</td><td>Convidar a mostrar uma prática e a apoiar os novos.</td></tr><tr><td>Quem se distrai</td><td>Usa o celular, corrige provas.</td><td>Combinar regras no início. Reuniões mais curtas e com atividade.</td></tr><tr><td>Quem leva para o lado pessoal</td><td>Sente-se criticado quando se fala em resultados.</td><td>Apresentar dados da escola, e não de pessoas. Conversar em particular.</td></tr></tbody></table></div><h3>Combinados do grupo</h3><p>Construa os combinados com a equipe no início do ano e deixe-os visíveis na sala de reunião.</p><ul class=\"chk\"><li><span></span>Começamos e terminamos no horário.</li><li><span></span>Celular guardado, salvo urgência.</li><li><span></span>Falamos de práticas e de dados, não de pessoas.</li><li><span></span>Discordamos com respeito e com proposta.</li><li><span></span>O que é dito sobre alunos fica na sala.</li><li><span></span>Saímos com encaminhamentos registrados.</li></ul>"},{"id":"c18","titulo":"Decidir em grupo","html":"<p>Nem toda decisão precisa de consenso. Dizer ao grupo como a decisão será tomada evita frustração.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Forma</th><th>Como funciona</th><th>Quando usar</th></tr></thead><tbody><tr><td>Informar</td><td>A decisão já está tomada. O grupo é informado e tira dúvidas.</td><td>Normas da rede e decisões da direção.</td></tr><tr><td>Consultar</td><td>O grupo opina. A coordenação ou a direção decide.</td><td>Quando há prazo curto ou responsabilidade legal.</td></tr><tr><td>Votar</td><td>A maioria decide.</td><td>Escolhas simples entre opções equivalentes.</td></tr><tr><td>Buscar consenso</td><td>O grupo conversa até chegar a algo que todos aceitam sustentar.</td><td>Decisões que dependem da adesão de todos, como regras comuns.</td></tr></tbody></table></div><figure><div class=\"matriz\"><div class=\"ey\">Impacto na aprendizagem</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Muito impacto, pouco esforço</b><small>Fazer primeiro.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Muito impacto, muito esforço</b><small>Planejar com prazo e dividir tarefas.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #5A6372\"><b>Pouco impacto, pouco esforço</b><small>Fazer se sobrar tempo.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Pouco impacto, muito esforço</b><small>Deixar de lado.</small></div></div><div class=\"ex\">Esforço</div></div><figcaption>Figura. Como escolher entre várias propostas.</figcaption></figure><h3>Quando não há acordo</h3><ul><li>Separe o que é fato do que é opinião.</li><li>Pergunte o que cada lado precisaria ver para mudar de ideia.</li><li>Proponha um teste por tempo limitado, com data para avaliar.</li><li>Registre a divergência com respeito e siga.</li></ul>"},{"id":"c19","titulo":"Do combinado ao resultado","html":"<p>O valor de uma reunião aparece nas semanas seguintes. Combinados sem acompanhamento ensinam à equipe que a reunião não é para valer.</p><h3>Quadro de encaminhamentos</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O quê</th><th>Quem</th><th>Até quando</th><th>Como saberemos que foi feito</th><th>Feito</th></tr></thead><tbody><tr><td>Retomar frações com material concreto no 6º ano</td><td>Professores de Matemática</td><td>15 dias</td><td>Relato na próxima reunião</td><td></td></tr><tr><td>Conversar com os responsáveis de quatro alunos</td><td>Coordenação</td><td>1 semana</td><td>Registro dos contatos</td><td></td></tr><tr><td> </td><td> </td><td> </td><td> </td><td> </td></tr><tr><td> </td><td> </td><td> </td><td> </td><td> </td></tr></tbody></table></div><ul><li>Poucos encaminhamentos: de três a cinco por reunião.</li><li>Cada um com um nome, e não \"todos\".</li><li>O quadro fica visível na sala dos professores.</li><li>A reunião seguinte começa por ele.</li><li>O que não foi feito é discutido sem bronca: o que impediu e do que a pessoa precisa.</li></ul><h3>Modelo de ata curta</h3><div class=\"rapido\"><p><b>Data:</b> ____/____/______ <b>Tipo de reunião:</b> ____________________ <b>Presentes:</b> ______ pessoas (lista anexa)</p><p><b>Objetivo:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que foi discutido (em três linhas):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que foi decidido:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Encaminhamentos:</b> ver quadro. <b>Próxima reunião:</b> ____/____/______</p></div><div class=\"nota\"><b>Ata serve para lembrar</b><br/>Uma ata de uma página, enviada no mesmo dia, é mais lida do que três páginas entregues uma semana depois.</div>"},{"id":"c20","titulo":"Comunicação entre as reuniões","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Canal</th><th>Bom para</th><th>Cuidados</th></tr></thead><tbody><tr><td>Aviso por escrito</td><td>Informes, datas e orientações.</td><td>Um envio por semana, em dia fixo, reúne tudo.</td></tr><tr><td>Grupo de mensagens</td><td>Lembretes rápidos e urgências.</td><td>Horário de uso combinado. Sem dados de alunos. Sem discussões longas.</td></tr><tr><td>Mural da sala dos professores</td><td>Calendário e quadro de encaminhamentos.</td><td>Atualizar toda semana.</td></tr><tr><td>Conversa individual</td><td>Apoio, devolutiva e assuntos pessoais.</td><td>Em local reservado.</td></tr><tr><td>Reunião on-line</td><td>Encontros curtos e formação com convidado.</td><td>Pauta ainda mais enxuta. Câmeras abertas. No máximo uma hora.</td></tr></tbody></table></div><h3>Reunião on-line: o que muda</h3><ul><li>Envie o material antes. Na tela, a leitura é mais lenta.</li><li>Faça uma pergunta a cada dez minutos e use o bate-papo.</li><li>Divida em salas pequenas para as discussões.</li><li>Peça que alguém cuide do bate-papo e do tempo.</li><li>Grave apenas se todos concordarem e não houver dados de alunos.</li></ul><div class=\"nota alerta\"><b>Dados de alunos fora dos grupos</b><br/>Nomes, notas, fotos e relatos sobre alunos não circulam em aplicativos de mensagens. A plataforma de reforço e os registros da escola são os lugares certos.</div>"},{"id":"c21","titulo":"Como saber se a reunião foi boa","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Sinal</th><th>Como verificar</th></tr></thead><tbody><tr><td>Havia um objetivo, e ele foi alcançado.</td><td>Compare o objetivo da pauta com o que foi registrado.</td></tr><tr><td>A maioria participou.</td><td>Conte quantas pessoas falaram.</td></tr><tr><td>Falou-se mais de ensino do que de avisos.</td><td>Estime o tempo de cada parte.</td></tr><tr><td>Houve decisão.</td><td>Veja o quadro de encaminhamentos.</td></tr><tr><td>Algo mudou na sala de aula.</td><td>Pergunte na reunião seguinte.</td></tr><tr><td>Terminou no horário.</td><td>Confira o relógio.</td></tr></tbody></table></div><h3>Avaliação rápida pelo grupo</h3><p>Nos dois minutos finais, peça que cada um registre em um papel, sem nome:</p><ul><li>Uma coisa que levo desta reunião.</li><li>Uma coisa que ficou confusa.</li><li>Uma sugestão para a próxima.</li></ul><h3>Autoavaliação de quem coordena</h3><ul class=\"chk\"><li><span></span>Enviei a pauta com antecedência.</li><li><span></span>Comecei pelos encaminhamentos anteriores.</li><li><span></span>Falei menos da metade do tempo.</li><li><span></span>Ouvi pessoas que costumam ficar caladas.</li><li><span></span>Usei dados sem expor professores nem alunos.</li><li><span></span>Cada encaminhamento saiu com nome e data.</li><li><span></span>Enviei o registro no mesmo dia.</li></ul><div class=\"pratica\"><div class=\"tt\">Para praticar · a próxima reunião</div><div class=\"q\"><b>1.</b> Qual será o objetivo da sua próxima reunião, em uma frase?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que técnica deste guia você vai usar para todos participarem?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Como você vai verificar se algo mudou depois?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c22","titulo":"Casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a reunião que virava reclamação</div><p><b>Situação.</b> Toda reunião de uma escola terminava em queixas sobre os alunos e as famílias. Nada era decidido.</p><p><b>O que fazer.</b></p><ol><li>Reconheça as dificuldades no início, em cinco minutos, com registro no quadro.</li><li>Separe o que a escola pode mudar do que não depende dela.</li><li>Escolha um item que depende da escola e trabalhe só nele.</li><li>Use a técnica dos papéis no quadro para levantar propostas.</li><li>Saia com dois encaminhamentos e volte a eles no encontro seguinte.</li></ol><p><b>Resultado esperado.</b> O grupo percebe que parte dos problemas tem solução ao alcance e passa a esperar resultado das reuniões.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o professor que não aceitava os dados</div><p><b>Situação.</b> Ao ver os resultados da turma, um professor diz que o diagnóstico não mede o que ele ensina.</p><p><b>O que fazer.</b></p><ol><li>Não discuta diante do grupo.</li><li>Peça que ele traga atividades da turma para analisar junto.</li><li>Compare o que as atividades mostram com o que o diagnóstico mostra.</li><li>Combine uma habilidade para retomar e verificar de novo.</li></ol><p><b>Resultado esperado.</b> O professor passa a usar o dado como uma informação a mais, ao lado do que ele já observa.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a formação que não chegava à sala</div><p><b>Situação.</b> A escola fez quatro encontros sobre leitura. Nas aulas, nada mudou.</p><p><b>O que fazer.</b></p><ol><li>No encontro seguinte, cada professor planeja uma atividade de leitura para a própria turma.</li><li>Cada um aplica em quinze dias e traz uma produção de aluno.</li><li>O grupo analisa as produções com o protocolo do capítulo sobre trabalhos dos alunos.</li><li>A coordenação visita duas aulas, a convite dos professores.</li></ol><p><b>Resultado esperado.</b> A formação passa a ter três tempos: estudar, aplicar e relatar.</p></div>"},{"id":"c23","titulo":"A semana pedagógica, dia a dia","html":"<p>A semana pedagógica abre o ano. O roteiro abaixo distribui três dias de trabalho, com metade do tempo reservada ao planejamento dos professores.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dia</th><th>Manhã</th><th>Tarde</th><th>Resultado do dia</th></tr></thead><tbody><tr><td>1</td><td>Acolhida da equipe. Apresentação dos novos. O que a escola fez bem no ano anterior. Leitura dos resultados, em grupos.</td><td>Escolha das prioridades do ano. Combinados da equipe.</td><td>Duas ou três prioridades escritas e combinados afixados.</td></tr><tr><td>2</td><td>Estudo do tema prioritário, com um exemplo de aula. Como o aluno estuda no reforço e como ler o mapa da turma.</td><td>Planejamento por ano ou área: primeiro bimestre.</td><td>Planos de ensino do bimestre esboçados.</td></tr><tr><td>3</td><td>Organização da escola: horários, espaços, calendário, primeira semana de aula. Proteção do aluno e plano de segurança.</td><td>Planejamento por ano ou área. Preparação da primeira reunião com os responsáveis.</td><td>Primeira semana planejada e plano de ação da escola.</td></tr></tbody></table></div><h3>A leitura dos resultados em grupos</h3><ol class=\"passos\"><li>Entregue a cada grupo os dados de um ano ou de uma área, sem nomes de alunos e de professores.</li><li>Peça que cada grupo responda: o que os dados mostram? O que nos surpreende? O que queremos entender melhor?</li><li>Cada grupo apresenta em dois minutos.</li><li>O coordenador registra no quadro os pontos comuns.</li><li>O grupo todo escolhe o que será prioridade.</li></ol><h3>A primeira semana de aula</h3><ul class=\"chk\"><li><span></span>Todos os professores sabem as suas turmas e horários.</li><li><span></span>A acolhida dos alunos está planejada, com atenção aos novos.</li><li><span></span>Os combinados de convivência serão construídos em cada turma.</li><li><span></span>Há uma atividade diagnóstica prevista para a primeira quinzena.</li><li><span></span>A data da reunião com os responsáveis foi definida.</li><li><span></span>Os acessos ao reforço escolar estão prontos para a entrega.</li></ul><div class=\"nota alerta\"><b>Cuide dos novos</b><br/>Quem chega à escola precisa de mais do que uma apresentação. Indique um colega de referência, entregue os documentos da escola e marque uma conversa individual na primeira semana.</div>"},{"id":"c24","titulo":"Acolher e formar professores iniciantes","html":"<p>Os primeiros anos de docência são os mais difíceis e os que mais definem a prática do professor. Uma escola que acompanha os iniciantes de perto ganha um profissional mais seguro e reduz os pedidos de remoção.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Período</th><th>O que a coordenação faz</th></tr></thead><tbody><tr><td>Antes do primeiro dia</td><td>Entrega o projeto pedagógico, o calendário, os horários e os planos do ano anterior. Apresenta a escola e a equipe.</td></tr><tr><td>Primeira semana</td><td>Indica um colega de referência, do mesmo ano ou área. Conversa sobre a rotina e os combinados da escola.</td></tr><tr><td>Primeiro mês</td><td>Encontro semanal de vinte minutos. Ajuda no planejamento. Visita a uma aula, combinada com antecedência.</td></tr><tr><td>Primeiro semestre</td><td>Encontro quinzenal. Convite para assistir à aula de um colega experiente. Devolutivas curtas.</td></tr><tr><td>Segundo semestre</td><td>Encontro mensal. Participação mais ativa nas reuniões. Balanço do ano.</td></tr></tbody></table></div><h3>As dificuldades mais comuns de quem começa</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Dificuldade</th><th>Como ajudar</th></tr></thead><tbody><tr><td>Organizar a turma</td><td>Ensinar a montar a rotina da aula e os procedimentos. Indicar o guia de turmas desafiadoras.</td></tr><tr><td>Planejar o tempo</td><td>Planejar junto as primeiras aulas, com os minutos de cada parte.</td></tr><tr><td>Lidar com níveis diferentes</td><td>Mostrar o mapa da turma e as estações de aprendizagem.</td></tr><tr><td>Avaliar</td><td>Analisar juntos produções de alunos e combinar critérios.</td></tr><tr><td>Conversar com responsáveis</td><td>Fazer junto a primeira conversa difícil.</td></tr><tr><td>Pedir ajuda</td><td>Perguntar toda semana: \"o que foi mais difícil?\"</td></tr></tbody></table></div><h3>O colega de referência</h3><ul><li>É voluntário e tem boa relação com a equipe.</li><li>Compartilha planos, materiais e experiências.</li><li>Recebe o iniciante na própria sala.</li><li>Não avalia. Apoia.</li><li>Tem esse trabalho reconhecido pela coordenação.</li></ul><div class=\"nota\"><b>O que dizer a quem começa</b><br/>\"Ninguém nasce sabendo dar aula. Aqui você não está sozinho.\" Essa frase, dita na primeira semana e confirmada na prática, muda o primeiro ano de um professor.</div>"},{"id":"c25","titulo":"O planejamento coletivo","html":"<p>O planejamento coletivo reúne professores do mesmo ano ou da mesma área para decidir o que será ensinado e como. Ele evita que cada sala siga um ritmo e garante que as habilidades prioritárias sejam trabalhadas por todos.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Etapa</th><th>Pergunta</th></tr></thead><tbody><tr><td>10 min</td><td>Olhar para trás</td><td>O que a turma aprendeu na última quinzena? O que não aprendeu?</td></tr><tr><td>10 min</td><td>Olhar os dados</td><td>O que o mapa da turma e as atividades mostram?</td></tr><tr><td>25 min</td><td>Planejar</td><td>O que ensinar nas próximas duas semanas? Com que atividades? Como saber se aprenderam?</td></tr><tr><td>10 min</td><td>Diferenciar</td><td>O que fazer com quem ainda não domina a base? E com quem já domina?</td></tr><tr><td>5 min</td><td>Combinar</td><td>O que cada um prepara? Quando voltamos a olhar?</td></tr></tbody></table></div><h3>Um plano de aula comum</h3><div class=\"rapido\"><p><b>Ano e componente:</b> ____________________ <b>Habilidade:</b> ____________________</p><p><b>O que o aluno vai saber fazer ao final:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que ele precisa saber antes (habilidade de base):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Como a aula começa:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Exemplo que o professor resolve:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Atividade dos alunos:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Como verificar se aprenderam:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Para quem precisa de mais apoio:</b> ____________________ <b>Para quem já domina:</b> ____________________</p></div><h3>O papel da coordenação</h3><ul><li>Garantir o horário e o espaço.</li><li>Trazer os dados da turma.</li><li>Fazer perguntas, em vez de dar o plano pronto.</li><li>Cuidar para que o grupo chegue a decisões.</li><li>Guardar os planos em lugar acessível a todos.</li><li>Visitar as aulas para ver o plano acontecer.</li></ul><div class=\"nota\"><b>Planejar junto, ensinar cada um do seu jeito</b><br/>O grupo combina a habilidade, a sequência e a forma de verificar. Cada professor adapta à própria turma.</div>"},{"id":"c26","titulo":"Preparar a reunião com os responsáveis","html":"<p>A reunião com os responsáveis é o principal encontro da escola com as famílias. Quando é só entrega de boletim e queixa, as famílias deixam de vir. A coordenação pode preparar os professores para um encontro que valha a presença.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que fazer</th></tr></thead><tbody><tr><td>Antes</td><td>Definir o objetivo. Convidar com uma semana de antecedência, por mais de um meio. Oferecer mais de um horário. Preparar com os professores o que será dito de cada turma.</td></tr><tr><td>Abertura coletiva</td><td>Dez minutos: boas-vindas, o que a escola está trabalhando no bimestre e como as famílias podem ajudar.</td></tr><tr><td>Por turma</td><td>O professor apresenta o que a turma aprendeu, mostra produções dos alunos e explica o reforço escolar.</td></tr><tr><td>Individual</td><td>Conversas reservadas, começando por um ponto forte do aluno. Nunca diante de outros responsáveis.</td></tr><tr><td>Escuta</td><td>Espaço para perguntas e sugestões, com registro.</td></tr><tr><td>Depois</td><td>Retorno às famílias sobre o que foi sugerido. Contato com quem não pôde vir.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Evite</th></tr></thead><tbody><tr><td>Mostrar o que os alunos produziram.</td><td>Ler notas em voz alta.</td></tr><tr><td>Falar de dificuldades em particular.</td><td>Citar alunos diante do grupo.</td></tr><tr><td>Dar uma orientação concreta para casa.</td><td>Dizer apenas \"precisa acompanhar mais\".</td></tr><tr><td>Usar linguagem simples.</td><td>Usar siglas e termos técnicos.</td></tr><tr><td>Terminar no horário.</td><td>Estender por horas.</td></tr><tr><td>Agradecer a presença.</td><td>Reclamar de quem não veio.</td></tr></tbody></table></div><h3>Ensaio com os professores</h3><p>Reserve vinte minutos de uma reunião pedagógica para ensaiar. Em duplas, um faz o papel do responsável e o outro, do professor. Situações para ensaiar:</p><ul><li>Comunicar uma dificuldade começando por um ponto forte.</li><li>Responder a um responsável que culpa a escola.</li><li>Explicar por que o reforço não dá nota.</li><li>Orientar uma família que não tem tempo ou não sabe ler.</li></ul>"},{"id":"c27","titulo":"Conflitos entre professores","html":"<p>Divergências sobre métodos, turmas e horários fazem parte de qualquer equipe. O problema começa quando viram disputas pessoais, grupos fechados e silêncio nas reuniões.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Sinal</th><th>O que pode estar acontecendo</th><th>O que fazer</th></tr></thead><tbody><tr><td>Dois professores não se falam</td><td>Um conflito não resolvido.</td><td>Conversar com cada um em separado e, depois, com os dois.</td></tr><tr><td>Grupos que sempre votam juntos</td><td>Disputa de influência.</td><td>Misturar os grupos nas atividades. Decidir com base em dados.</td></tr><tr><td>Comentários na sala dos professores</td><td>Insatisfação que não chega à reunião.</td><td>Abrir espaço para críticas, com regras de respeito.</td></tr><tr><td>Um professor desautoriza outro diante dos alunos</td><td>Falta de combinados comuns.</td><td>Conversa individual e combinados da equipe.</td></tr><tr><td>Silêncio nas reuniões</td><td>Medo de se expor.</td><td>Trabalho em duplas e escrita antes da fala.</td></tr></tbody></table></div><h3>A conversa de mediação</h3><ol class=\"passos\"><li>Ouça cada pessoa em separado, sem tomar partido.</li><li>Pergunte o que aconteceu, o que cada um precisa e o que estaria disposto a fazer.</li><li>Reúna os dois em local reservado.</li><li>Estabeleça as regras: um fala por vez, fala-se de fatos, sem ofensas.</li><li>Cada um expõe o seu ponto. O outro repete o que entendeu.</li><li>Busquem um combinado concreto, pequeno e possível.</li><li>Marque uma data para verificar.</li></ol><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · abrindo a mediação</div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Chamei vocês porque os dois são importantes para a escola e percebo que algo não vai bem. Quero ouvir cada um, sem interrupção.</div></div><div class=\"f o\"><div class=\"q\">Professor A</div><div class=\"b\">Ela muda os combinados da turma sem me avisar.</div></div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Obrigada. Professora, o que você ouviu?</div></div><div class=\"f o\"><div class=\"q\">Professora B</div><div class=\"b\">Que ele se sente desrespeitado quando eu mudo as regras.</div></div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">E como você vê a situação?</div></div></div><div class=\"nota alerta\"><b>Quando não é conflito, é assédio</b><br/>Humilhação repetida, isolamento e ameaça não se resolvem por mediação. São levados à direção e apurados conforme as normas da rede.</div>"},{"id":"c28","titulo":"Banco de pautas prontas","html":"<p>As pautas abaixo podem ser usadas ao longo do ano, na ordem que fizer sentido para a escola. Cada uma cabe em uma hora.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tema</th><th>Objetivo</th><th>Atividade principal</th><th>Resultado</th></tr></thead><tbody><tr><td>Ler o mapa da turma</td><td>Cada professor identifica a habilidade a retomar.</td><td>Em duplas, abrir o mapa de uma turma e responder às três perguntas da semana.</td><td>Uma habilidade escolhida por turma.</td></tr><tr><td>Aula de retomada</td><td>Planejar uma aula a partir de uma habilidade de base.</td><td>Usar o roteiro de cinquenta minutos e preencher o plano comum.</td><td>Uma aula pronta por dupla.</td></tr><tr><td>Leitura em todas as áreas</td><td>Combinar uma estratégia de leitura comum.</td><td>Analisar um enunciado de cada disciplina e listar o que dificulta.</td><td>Uma estratégia adotada por todos.</td></tr><tr><td>Combinados da escola</td><td>Alinhar regras e respostas ao descumprimento.</td><td>Papéis no quadro: que regras temos? Quais todos aplicam?</td><td>Três combinados comuns.</td></tr><tr><td>Analisar produções</td><td>Alinhar o que é um bom trabalho.</td><td>Protocolo de análise de três produções.</td><td>Critérios comuns de correção.</td></tr><tr><td>Proteção do aluno</td><td>Rever o fluxo de comunicação.</td><td>Estudo de um caso do guia de proteção.</td><td>Fluxo afixado e referências definidas.</td></tr><tr><td>Alunos que aprendem de outro jeito</td><td>Combinar adaptações comuns.</td><td>Estudo de caso de um aluno, com a ficha.</td><td>Estratégias adotadas por todos os professores do aluno.</td></tr><tr><td>Conversas com responsáveis</td><td>Preparar a reunião de responsáveis.</td><td>Ensaio em duplas.</td><td>Roteiro da reunião.</td></tr><tr><td>Avaliação que ensina</td><td>Rever instrumentos e devolutivas.</td><td>Cada um traz uma prova e analisa com o colega o que ela mede.</td><td>Um ajuste em cada instrumento.</td></tr><tr><td>Balanço do bimestre</td><td>Ver o que funcionou.</td><td>Rodada: uma prática que manteria e uma que mudaria.</td><td>Lista do que manter e do que mudar.</td></tr></tbody></table></div><h3>Aberturas de cinco minutos</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Abertura</th><th>Como fazer</th></tr></thead><tbody><tr><td>Uma boa notícia</td><td>Cada um conta algo que deu certo na semana.</td></tr><tr><td>O aluno que me surpreendeu</td><td>Três voluntários contam um avanço de um aluno, sem nome.</td></tr><tr><td>Uma palavra</td><td>Cada um diz uma palavra sobre como chega à reunião.</td></tr><tr><td>A pergunta do dia</td><td>Uma pergunta ligada à pauta, respondida em duplas.</td></tr><tr><td>O objeto</td><td>Um material de aula é passado, e cada um diz como o usaria.</td></tr><tr><td>Agradecimento</td><td>Cada um agradece a um colega por algo concreto.</td></tr></tbody></table></div>"},{"id":"c29","titulo":"Devolutiva de avaliações da rede","html":"<p>Quando chegam os resultados de uma avaliação da rede ou nacional, a reunião de devolutiva decide se eles vão mudar algo ou apenas gerar desânimo.</p><ol class=\"passos\"><li>Estude os resultados antes, com a direção.</li><li>Prepare os dados da escola por ano e por nível de aprendizagem, sem identificar professores.</li><li>Comece pelo que avançou.</li><li>Apresente os números com clareza, sem adjetivos.</li><li>Entregue aos grupos os itens ou as habilidades com mais erros.</li><li>Peça que cada grupo responda: o que esta questão exige? Onde os alunos erram? O que precisamos ensinar?</li><li>Feche com duas ou três ações, com responsáveis e prazos.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Reação do grupo</th><th>Como conduzir</th></tr></thead><tbody><tr><td>\"A prova não mede o que ensinamos.\"</td><td>Olhar junto o que ela mede e comparar com o plano de ensino.</td></tr><tr><td>\"O problema vem dos anos anteriores.\"</td><td>Reconhecer e perguntar o que pode ser feito a partir de agora, em todos os anos.</td></tr><tr><td>\"Com esses alunos, não dá.\"</td><td>Mostrar alunos e turmas em condições parecidas que avançaram.</td></tr><tr><td>\"Vamos treinar para a prova.\"</td><td>Lembrar que o objetivo é a habilidade. O treino de formato ocupa pouco tempo.</td></tr><tr><td>Silêncio e desânimo</td><td>Trabalhar em duplas e começar por uma ação pequena.</td></tr></tbody></table></div><h3>Juntar as fontes</h3><ul><li>As avaliações externas mostram o retrato de um momento.</li><li>As habilidades prioritárias do reforço mostram, semana a semana, onde há mais alunos em Ainda não.</li><li>As atividades de sala mostram o raciocínio do aluno.</li><li>Quando as três fontes apontam para a mesma habilidade, a prioridade está dada.</li></ul><div class=\"nota\"><b>Resultado não é sentença</b><br/>O dado diz onde a escola está, e não até onde ela pode chegar. A reunião termina quando o grupo sabe o que fará na segunda-feira.</div>"},{"id":"c30","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"Como conduzir\"</td><td>Quanto tempo das nossas reuniões é usado para ensino? O que queremos mudar?</td></tr><tr><td>2</td><td>De \"Situações difíceis\" até \"A pauta que funciona\"</td><td>As nossas pautas dizem o que queremos alcançar? Como é o nosso calendário de reuniões?</td></tr><tr><td>3</td><td>De \"Técnicas para todos participarem\" até \"Conselho de classe\"</td><td>Que técnica vamos testar? O que muda no nosso conselho?</td></tr><tr><td>4</td><td>De \"Analisar trabalhos\" até \"Decidir em grupo\"</td><td>Como a observação de aula é vista aqui? Como tomamos decisões?</td></tr><tr><td>5</td><td>De \"Do combinado ao resultado\" até o final</td><td>Os nossos encaminhamentos são acompanhados? Como vamos avaliar as reuniões?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c31","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Uma boa reunião pedagógica termina com:</p><ol type=\"a\"><li>Todos os avisos dados.</li><li>Uma decisão sobre a prática e uma data para conferir.</li><li>Uma ata longa.</li><li>A fala da coordenação.</li></ol></div><div class=\"qz\"><p><b>2.</b> Ao apresentar os dados do reforço, o adequado é:</p><ol type=\"a\"><li>Mostrar a habilidade e o percentual por nível.</li><li>Mostrar só as turmas com pior resultado.</li><li>Projetar os nomes dos alunos.</li><li>Comparar professores.</li></ol></div><div class=\"qz\"><p><b>3.</b> Diante do silêncio da equipe, uma boa técnica é:</p><ol type=\"a\"><li>Encerrar a reunião.</li><li>Chamar alguém pelo nome.</li><li>Pedir conversa em duplas antes do grupo.</li><li>Repetir a pergunta mais alto.</li></ol></div><div class=\"qz\"><p><b>4.</b> O registro dos combinados deve ter:</p><ol type=\"a\"><li>Apenas a lista de presentes.</li><li>Os nomes dos alunos com dificuldade.</li><li>A opinião da coordenação.</li><li>O quê, quem, até quando e como saberemos.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> b) Uma decisão sobre a prática e uma data para conferir. O foco é a mudança na prática.</p><p><b>2.</b> a) Mostrar a habilidade e o percentual por nível. Os dados não servem para expor.</p><p><b>3.</b> c) Pedir conversa em duplas antes do grupo. A dupla reduz o medo de exposição.</p><p><b>4.</b> d) O quê, quem, até quando e como saberemos. Sem responsável e prazo, o combinado se perde.</p></div>"},{"id":"c32","titulo":"Glossário","html":"<dl><dt>Ata</dt><dd>Registro escrito do que foi discutido e decidido em uma reunião.</dd><dt>Conselho de classe</dt><dd>Reunião periódica que avalia o percurso das turmas e dos alunos e decide encaminhamentos.</dd><dt>Devolutiva</dt><dd>Retorno dado a alguém sobre o seu trabalho, com base em fatos, para ajudar a melhorar.</dd><dt>Encaminhamento</dt><dd>Ação combinada em reunião, com responsável e prazo.</dd><dt>Estudo de caso</dt><dd>Discussão organizada sobre um aluno ou uma turma, que termina com um plano.</dd><dt>Formação continuada</dt><dd>Estudo dos professores ao longo da carreira, ligado à prática.</dd><dt>Habilidade prioritária</dt><dd>Habilidade em que há mais alunos em Ainda não e que merece atenção primeiro.</dd><dt>Hora de trabalho coletivo</dt><dd>Parte da jornada do professor destinada a estudo, planejamento e avaliação com a equipe.</dd><dt>Mediação</dt><dd>Conversa conduzida por uma terceira pessoa para ajudar duas partes a chegar a um acordo.</dd><dt>Pauta</dt><dd>Roteiro da reunião, com objetivo, assuntos, tempo e resultado esperado.</dd><dt>Plano de ação</dt><dd>Documento com as prioridades, metas e ações da escola para o ano.</dd><dt>Planejamento coletivo</dt><dd>Encontro de professores do mesmo ano ou área para decidir o que e como ensinar.</dd><dt>Protocolo</dt><dd>Sequência combinada de passos para conduzir uma discussão.</dd><dt>Semana pedagógica</dt><dd>Período de planejamento e formação da equipe antes do início das aulas.</dd></dl>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"O tempo de trabalho coletivo do professor é:","alternativas":["Parte da jornada prevista em lei.","Opcional.","Exclusivo para avisos.","Um favor da escola."],"correta":0,"explicacao":"A lei reserva parte da jornada para estudo e planejamento."},{"pergunta":"Uma boa pauta traz:","alternativas":["Apenas os avisos.","O nome de quem errou.","Uma lista de assuntos.","O objetivo, o tempo e o resultado esperado de cada item."],"correta":3,"explicacao":"A pauta diz o que se quer alcançar."},{"pergunta":"Na técnica \"um, dois, todos\", o primeiro passo é:","alternativas":["Votar.","O grupo discutir.","Cada pessoa pensar sozinha.","A coordenação responder."],"correta":2,"explicacao":"Pensar sozinho garante que todos tenham algo a dizer."},{"pergunta":"No estudo de caso de um aluno, o grupo começa por:","alternativas":["Listar os defeitos do aluno.","Descrever fatos e o que já funciona.","Chamar a família.","Definir a punição."],"correta":1,"explicacao":"Fatos e pontos fortes orientam as estratégias."},{"pergunta":"O conselho de classe deve terminar com:","alternativas":["Um aviso geral.","A leitura das notas.","Encaminhamentos com responsável e data.","A lista dos piores alunos."],"correta":2,"explicacao":"Sem encaminhamento, o conselho não muda nada."},{"pergunta":"Na devolutiva de uma aula observada, o coordenador:","alternativas":["Entrega uma lista de erros.","Começa pelo que o professor percebeu e combina um ponto de melhoria.","Fala diante da turma.","Compara com outros professores."],"correta":1,"explicacao":"Um ponto por vez, escolhido pelo professor."},{"pergunta":"Uma formação muda a prática quando:","alternativas":["É feita só com palestras.","Acontece uma vez por ano.","Troca de tema a cada encontro.","Inclui estudar, aplicar na turma e relatar."],"correta":3,"explicacao":"O ciclo completo é o que leva a ideia à sala."},{"pergunta":"Dados de alunos em grupos de mensagens:","alternativas":["Não devem circular.","Podem circular à noite.","Dependem do professor.","São permitidos se o grupo for fechado."],"correta":0,"explicacao":"A plataforma e os registros da escola são os lugares certos."}];
